import{_ as t}from"./chunks/06-js-core.D6-zQz5Q.js";import{_ as s,o as i,c as a,a2 as r}from"./chunks/framework.Dbgp30TS.js";const b=JSON.parse('{"title":"06 · JS 侧核心：看不见的管家们","description":"","frontmatter":{},"headers":[],"relativePath":"comics/06-js-core.md","filePath":"comics/06-js-core.md","lastUpdated":1794291790000}'),o={name:"comics/06-js-core.md"};function n(c,e,l,d,p,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_06-·-js-侧核心-看不见的管家们" tabindex="-1">06 · JS 侧核心：看不见的管家们 <a class="header-anchor" href="#_06-·-js-侧核心-看不见的管家们" aria-label="Permalink to &quot;06 · JS 侧核心：看不见的管家们&quot;">​</a></h1><p><img src="'+t+`" alt="看不见的管家们：InitializeCore / Pressability / Animated / VirtualizedList"></p><p>前几章的主角都是&quot;跨语言通信&quot;这类大工程。这一章换一班人马：四位常驻 JS 世界的管家。他们平时不出镜，但你写下的每一行 RN 代码，背后都有他们在值班。</p><h2 id="一、开机管家-initializecore" tabindex="-1">一、开机管家：InitializeCore <a class="header-anchor" href="#一、开机管家-initializecore" aria-label="Permalink to &quot;一、开机管家：InitializeCore&quot;">​</a></h2><p>每个 App 的 JS bundle 执行的第一份&quot;实质文件&quot;就是它。但 0.87 里，[InitializeCore.js:L13-L37](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Core/InitializeCore.js#L13-L37) 已经瘦成一具壳——注释里明说&quot;此文件只是兼容入口，真正逻辑在 setup&quot;。真正的活由 [src/setup-env.js:L14-L22](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/src/setup-env.js#L14-L22) 委托给 <code>setUpDefaultReactNativeEnvironment</code>：</p><ul><li>装上全局 polyfill 与错误上报通道；</li><li>打性能标记（TTRC 时长统计的起点）；</li><li>注册核心可回调模块（BatchedBridge 的&quot;通讯簿&quot;）。</li></ul><blockquote><p>记住这个分层：<strong>壳 → setup-env → private/setup</strong>。官方在把&quot;启动时必须做的事&quot;一路下沉、逐件瘦身——这正是 0.87 秒开优化的主线剧情。</p></blockquote><h2 id="二、触控管家-pressability" tabindex="-1">二、触控管家：Pressability <a class="header-anchor" href="#二、触控管家-pressability" aria-label="Permalink to &quot;二、触控管家：Pressability&quot;">​</a></h2><p>你写的 <code>onPress</code> 其实是台词，真正演出的是 [Pressability.js](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Pressability/Pressability.js)。它内部是一台显式状态机：[L663-L698](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Pressability/Pressability.js#L663-L698) 的 <code>Transitions</code> 表写清了每个事件在什么状态下触发什么迁移。</p><p>而 [L447-L549](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Pressability/Pressability.js#L447-L549) 是落点分流：<code>responderGrant</code>（抢到触摸权）→ <code>responderRelease</code>（松手）→ <code>onClick</code> → 最终触发你的 <code>onPress</code>。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按下 ──grant──▶ 按住 ──release──▶ 判定 ──▶ onPress</span></span>
<span class="line"><span>        │                │</span></span>
<span class="line"><span>        └─ 移出边界 ─▶ pressOut（取消）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这套机制统一解决了：手指滑出按钮取消点击、长按、双击误触、触摸延迟等问题——所以<strong>永远用 onPress 而别自己监听原生触摸</strong>，除非你在做手势库。</p><h2 id="三、动画管家-animated" tabindex="-1">三、动画管家：Animated <a class="header-anchor" href="#三、动画管家-animated" aria-label="Permalink to &quot;三、动画管家：Animated&quot;">​</a></h2><p>Animated 的第一决策点在 [Animation.js:L54-L58](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Animated/src/nodes/Animation.js#L54-L58)：<code>useNativeDriver</code> 为 true 时，整段动画（时长、曲线、循环）被一次性打包，经 <code>startAnimatingNode</code>（[L126-L180](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Animated/src/nodes/Animation.js#L126-L180)）送进原生，由原生时钟逐帧驱动——<strong>JS 线程卡死动画也不卡</strong>。</p><p>指令的运输还有个省流设计：[NativeAnimatedHelper.js:L89-L164](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Animated/src/NativeAnimatedHelper.js#L89-L164) 的 <code>singleOpQueue</code> 把零散操作攒成批量单条指令再发车。</p><blockquote><p>旧时代的属性驱动（<code>setValue</code> 逐次跨桥）每帧一次往返；新架构下连&quot;发车&quot;都批量化了。组件篇的 Bouncy Checkbox、Skeleton 都建在这套地基上。</p></blockquote><h2 id="四、列表管家-virtualizedlist" tabindex="-1">四、列表管家：VirtualizedList <a class="header-anchor" href="#四、列表管家-virtualizedlist" aria-label="Permalink to &quot;四、列表管家：VirtualizedList&quot;">​</a></h2><p>FlatList 的全部滚动魔法都来自 VirtualizedList。它在 0.87 里的身份是个&quot;二传手&quot;：[VirtualizedList.js:L13-L20](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Lists/VirtualizedList.js#L13-L20) 只是把实现从 <code>@react-native/virtualized-lists</code> 包<strong>再导出</strong>——官方把核心算法拆成独立 npm 包，方便单独发版修 bug。</p><p>核心思想一句话：<strong>窗口化</strong>——只渲染视口附近几十条，滚近补货、滚远回收。而 [FlatList.js:L83-L95](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Lists/FlatList.js#L83-L95) 的 <code>getItemLayout</code> 能让它跳过逐项测量、直飞目标行——这就是&quot;跳到指定条目&quot;瞬间完成的原因。</p><h2 id="五、faq" tabindex="-1">五、FAQ <a class="header-anchor" href="#五、faq" aria-label="Permalink to &quot;五、FAQ&quot;">​</a></h2><p><strong>Q1：InitializeCore 里的代码我能改吗？</strong> 不要改源码——它有 <code>setUpReactNativeEnvironment</code> 之类的官方注入点；业务初始化请放入口文件 <code>index.js</code> 里 <code>AppRegistry.registerComponent</code> 之前。</p><p><strong>Q2：为什么我的 onPress 有时会&quot;失灵&quot;？</strong> 先查状态机两件事：是否在 release 前手指滑出了按压区；是否父级用可滚动手势抢走了 responder。状态机是严格按 Transitions 表走的，不是玄学。</p><p><strong>Q3：useNativeDriver 能驱动所有属性吗？</strong> 不能——只支持非布局属性（transform、opacity 等）。布局属性（width/height）走原生驱动需要布局系统参与，得用 Reanimated 的 layout 动画或手势方案。</p><hr><blockquote><p>下一章：<a href="./07-android">07 · Android 内幕</a>——Kotlin 工厂与 JNI 地道。</p></blockquote>`,25)])])}const m=s(o,[["render",n]]);export{b as __pageData,m as default};
